import java.io.*
import java.util.*

fun main() {
    val st = StringTokenizer(BufferedReader(InputStreamReader(System.`in`)).readLine())
    val n = st.nextToken().toInt()
    var k = st.nextToken().toLong()
    val f = LongArray(n + 2)
    f[0] = 1
    if (n + 1 >= 1) f[1] = 1
    for (i in 2..n + 1) {
        f[i] = f[i - 1] + f[i - 2]
        if (f[i] > 2_000_000_000_000_000_000L) f[i] = 2_000_000_000_000_000_000L
    }
    val res = IntArray(n + 1)
    var i = 1
    while (i <= n) {
        val rem = n - i
        if (k <= f[rem]) {
            res[i] = i
            i += 1
        } else {
            k -= f[rem]
            res[i] = i + 1
            res[i + 1] = i
            i += 2
        }
    }
    val sb = StringBuilder()
    for (j in 1..n) {
        if (j > 1) sb.append(' ')
        sb.append(res[j])
    }
    println(sb)
}
